<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <title>Personal Expense Tracker</title>
  <style>
    #form-error {
      color: red;
      margin-top: 5px;
    }
    .expense {
      display: flex;
      justify-content: space-between;
      align-items: center;
      border-bottom: 1px solid #ccc;
      padding: 8px 0;
    }
    .cat-total {
      margin-top: 4px;
    }
  </style>
</head>
<body>
  <h1>Expense Tracker</h1>

  <!-- Entry Form -->
  <form id="expense-form">
    <div>
      Amount: <input type="number" id="amount" required />
    </div>
    <div>
      Category:
      <select id="category">
        <option value="groceries">Groceries</option>
        <option value="transport">Transport</option>
        <option value="bills">Bills</option>
        <option value="fun">Fun</option>
      </select>
    </div>
    <div>
      Date: <input type="date" id="date" required />
    </div>
    <div>
      Note (optional): <textarea id="note"></textarea>
    </div>
    <button type="submit" id="add-expense">Add Expense</button>
    <div id="form-error"></div>
  </form>

  <!-- Filters -->
  <div style="margin-top:16px;">
    Filter by category:
    <select id="filter-category">
      <option value="all">All</option>
      <option value="groceries">Groceries</option>
      <option value="transport">Transport</option>
      <option value="bills">Bills</option>
      <option value="fun">Fun</option>
    </select>
    From date: <input type="date" id="filter-from" />
    To date: <input type="date" id="filter-to" />
  </div>

  <!-- Expense List -->
  <div id="expense-list" style="margin-top:16px;"></div>

  <!-- Summary -->
  <h2>Summary</h2>
  <div>Total: <span id="total">0.00</span></div>
  <div class="cat-totals">
    <div data-cat="groceries" class="cat-total"></div>
    <div data-cat="transport" class="cat-total"></div>
    <div data-cat="bills" class="cat-total"></div>
    <div data-cat="fun" class="cat-total"></div>
  </div>

  <script>
    let expenses = [];

    function saveExpenses() {
      localStorage.setItem('expenses', JSON.stringify(expenses));
    }

    function handleAddExpense(e) {
      e.preventDefault();
      const amountInput = document.getElementById("amount");
      const categoryEl = document.getElementById("category");
      const dateInput = document.getElementById("date");
      const formErrorEl = document.getElementById("form-error");

      const amount = parseFloat(amountInput.value);
      const selectedCategory = categoryEl.value;
      const date = dateInput.value;

      if (isNaN(amount) || amount <= 0 || !date) {
        formErrorEl.textContent =
          "Invalid amount or missing date.";
        return;
      } else {
        formErrorEl.textContent = "";
      }

      expenses.unshift({
        amount,
        category: selectedCategory,
        date,
        note: document.getElementById("note").value
      });
      saveExpenses();
      render();

      amountInput.value = "";
    }

    function handleDelete(index) {
      expenses.splice(index, 1);
      saveExpenses();
      render();
    }

    function render() {
      const expenseList = document.getElementById("expense-list");

      // Clear list
      expenseList.innerHTML = "";

      // Get filter values
      const categoryFilter = document.getElementById("filter-category").value;
      const fromDate = document.getElementById("filter-from").value;
      const toDate = document.getElementById("filter-to").value;

      // Filter expenses
      let visibleExpenses = expenses.map((exp, i) => ({ ...exp, index: i })).filter(obj => {
        const catOk = categoryFilter === "all" || obj.category === categoryFilter;
        let dateOk = true;
        if (fromDate && obj.date < fromDate) dateOk = false;
        if (toDate && obj.date > toDate) dateOk = false;
        return catOk && dateOk;
      });

      // Render filtered expenses
      for (let i = 0; i < visibleExpenses.length; i++) {
        const { amount, category, date, index } = visibleExpenses[i];
        const rowDiv = document.createElement("div");
        rowDiv.className = "expense";
        rowDiv.innerHTML = `
          <span>$${amount.toFixed(2)}</span>
          <span>${category}</span>
          <span>${date}</span>
          <button class="exp-del">Delete</button>
        `;
        const delBtn = rowDiv.querySelector(".exp-del");
        delBtn.addEventListener("click", () => handleDelete(index));
        expenseList.appendChild(rowDiv);
      }

      // Update totals
      const totalAmount = visibleExpenses.reduce((sum, exp) => sum + exp.amount, 0).toFixed(2);
      document.getElementById("total").textContent = totalAmount;

      // Per-category totals
      const catTotals = {};
      visibleExpenses.forEach(exp => {
        if (!catTotals[exp.category]) {
          catTotals[exp.category] = 0;
        }
        catTotals[exp.category] += exp.amount;
      });

      document.querySelectorAll(".cat-total").forEach(el => {
        const category = el.getAttribute("data-cat");
        let total = catTotals[category] || 0;
        el.textContent = `$${total.toFixed(2)}`;
      });
    }

    // Load and initialize
    document.addEventListener("DOMContentLoaded", () => {
      expenses = JSON.parse(localStorage.getItem("expenses")) || [];

      document.getElementById("expense-form").addEventListener("submit", handleAddExpense);
      document.getElementById("filter-category").addEventListener("change", render);
      document.getElementById("filter-from").addEventListener("input", render);
      document.getElementById("filter-to").addEventListener("input", render);

      // Initial render
      render();
    });
  </script>
</body>
</html>
